<script setup lang="ts">
import { ref,onMounted,onUnmounted } from 'vue'
import { NButton,NDrawer,NDrawerContent,NSelect } from 'naive-ui'
import { api,post,rows,str,state,pretty,APIError,message,type Row } from '../api'
import Notice from '../components/Notice.vue'
import AppIcon from '../components/AppIcon.vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import { t, formatDateTime, formatNumber, displayState, displayTaskType } from '../i18n'
const page=ref(0),hasNext=ref(false),pageSize=50,actionBusy=ref(false),tasks=ref<Row[]>([]),error=ref<unknown>(''),busy=ref(false),selected=ref<Row|null>(null),logs=ref<Row[]>([]),filter=ref(''),connected=ref(false),confirm=ref(false)
const stageKeys: Record<string, string> = {"starting": "stageStarting", "completed": "stageCompleted", "Canceled": "stageCanceled", "creating replacement": "stageCreatingReplacement", "replacement verified": "stageReplacementVerified", "stopping original": "stageStoppingOriginal", "verified": "stageVerified", "complete": "stageComplete", "pulling": "stagePulling", "scanning": "stageScanning", "backup": "stageBackup", "commit_verification": "stageCommitVerification", "preflight": "stagePreflight", "prepare_worker_image": "stagePrepareWorkerImage", "read_data_verification": "stageReadDataVerification", "retention": "stageRetention", "stop_writers": "stageStopWriters", "verify_manifest": "stageVerifyManifest", "deploy": "stageDeploy", "validate": "stageValidate", "verify": "stageVerify", "restart": "stageRestart", "write": "stageWrite", "recreate_and_verify_services": "stageRecreateVerifyServices", "restore_and_verify_content": "stageRestoreVerifyContent", "verify_metadata": "stageVerifyMetadata"}
function displayStage(value: unknown) { const raw = str(value); return Object.hasOwn(stageKeys, raw) ? t(`tasks.${stageKeys[raw]}`) : raw }
let stream:EventSource|undefined,refreshTimer:ReturnType<typeof setTimeout>|undefined
async function load(){busy.value=true;try{const pageRows=rows(await api(`/tasks?limit=${pageSize+1}&offset=${page.value*pageSize}`));hasNext.value=pageRows.length>pageSize;tasks.value=pageRows.slice(0,pageSize);error.value='';if(selected.value){const id=selected.value.id;selected.value=await api(`/tasks/${id}`);logs.value=rows(await api(`/tasks/${id}/logs`))}}catch(e){error.value=e}finally{busy.value=false}}
async function inspect(task:Row){selected.value=task;try{logs.value=rows(await api(`/tasks/${task.id}/logs`))}catch(e){error.value=e}}
async function cancel(){if(!selected.value||actionBusy.value)return;actionBusy.value=true;try{await post(`/tasks/${selected.value.id}/cancel`);confirm.value=false;await load()}catch(e){error.value=e}finally{actionBusy.value=false}}
function receive(){clearTimeout(refreshTimer);refreshTimer=setTimeout(load,150)}
onMounted(()=>{void load();stream=new EventSource('/api/v1/events');stream.onopen=()=>connected.value=true;stream.onerror=()=>connected.value=false;stream.onmessage=receive;for(const event of ['task.created','task.started','task.progress','task.log','task.finished'])stream.addEventListener(event,receive)});onUnmounted(()=>{stream?.close();clearTimeout(refreshTimer)})
</script>
<template><div class="toolbar"><span class="connection"><i class="status-dot" :class="{offline:!connected}"/>{{ connected?t('tasks.connected'):t('tasks.reconnecting') }}</span><div class="actions"><n-select filterable v-model:value="filter" class="status-select" :input-props="{'aria-label':t('tasks.filterAria')}" :options="[{label:t('tasks.allStates'),value:''},...['Pending','Running','Succeeded','Failed','Canceled'].map(v=>({label:displayState(v),value:v}))]"/><n-button :loading="busy" @click="load"><AppIcon name="refresh"/>{{ t('tasks.refresh') }}</n-button></div></div><Notice :error="error"/><section class="panel table-panel"><div class="panel-title"><h3>{{ t('tasks.records') }} <span class="count">{{ formatNumber(tasks.length) }}</span></h3><span class="eyebrow">{{ t('tasks.journal') }}</span></div><div class="table-scroll"><table><thead><tr><th>{{ t('tasks.typeId') }}</th><th>{{ t('tasks.target') }}</th><th>{{ t('tasks.status') }}</th><th>{{ t('tasks.progress') }}</th><th>{{ t('tasks.createdAt') }}</th><th>{{ t('tasks.actions') }}</th></tr></thead><tbody><tr v-for="task in tasks.filter(t=>!filter||state(t)===filter)" :key="str(task.id)"><td><strong>{{ displayTaskType(task.type??task.kind) }}</strong><code>{{ str(task.id).slice(0,16) }}</code></td><td>{{ str(task.target) }}</td><td><span class="tag" :class="state(task).toLowerCase()">{{ displayState(state(task)) }}</span></td><td><span>{{ displayStage(task.stage) }}</span><div class="progress-track"><span :style="{width:`${Number(task.progress??0)}%`}"/></div></td><td>{{ formatDateTime(task.created_at) }}</td><td><n-button size="small" @click="inspect(task)">{{ t('tasks.viewLogs') }}</n-button></td></tr></tbody></table></div><Notice :busy="busy&&!tasks.length" :empty="!busy&&!tasks.length"/><div class="pagination"><span>{{ t('tasks.pagination', { page: formatNumber(page+1), count: formatNumber(tasks.length) }) }}</span><div class="actions"><n-button size="small" :disabled="busy||page===0" @click="page--;load()">{{ t('tasks.previous') }}</n-button><n-button size="small" :disabled="busy||!hasNext" @click="page++;load()">{{ t('tasks.next') }}</n-button></div></div></section><n-drawer :show="Boolean(selected)" :width="'min(800px,100vw)'" @update:show="v=>!v&&(selected=null)"><n-drawer-content :title="t('tasks.details')" closable><template v-if="selected"><Notice :error="error"/><div class="toolbar"><span class="tag" :class="state(selected).toLowerCase()">{{ displayState(state(selected)) }}</span><n-button type="error" :disabled="!selected.cancellable||!['Pending','Running'].includes(state(selected))" @click="error='';confirm=true">{{ t('tasks.cancel') }}</n-button></div><p v-if="!selected.cancellable" class="muted">{{ t('tasks.cannotCancel') }}</p><p v-if="selected.error_message" class="notice error">{{ selected.error_code }} · {{ message(new APIError(0, str(selected.error_code), str(selected.error_message))) }}</p><pre class="json-block">{{ pretty(selected) }}</pre><h3>{{ t('tasks.logs') }}</h3><pre class="terminal">{{ logs.map(l=>`${str(l.created_at)} ${str(l.message)}`).join('\n')||t('tasks.noLogs') }}</pre></template></n-drawer-content></n-drawer><ConfirmDialog v-model:show="confirm" :title="t('tasks.cancel')" :error="error" :busy="actionBusy" :detail="t('tasks.cancelWarning')" @confirm="cancel"/></template>
